require_once dirname(__DIR__, 3) . '/bootstrap.php'; $allowedRoles=[ROLE_HOUSE_MASTER,ROLE_HOUSE_MISTRESS]; require APP_ROOT.'/app/middleware/RoleMiddleware.php'; use App\Services\IncidentService; use App\Services\StudentService;
$houseId=current_user()['houseId']??null;$students=StudentService::all($houseId);if($_SERVER['REQUEST_METHOD']==='POST'){ $studentId=sanitize($_POST['studentId']??'');$valid=array_filter($students,fn($student)=>(string)($student['id']??'')===$studentId);if(!$valid){flash('error','Select a student from your assigned house.');}else{$result=(new IncidentService())->create(['title'=>sanitize($_POST['title']??''),'description'=>sanitize($_POST['description']??''),'studentId'=>$studentId,'priority'=>sanitize($_POST['priority']??'medium'),'reportedBy'=>current_user()['uid']??current_user()['id']??null]);flash($result['success']?'success':'error',$result['message']);if($result['success'])redirect(url('views/house-master/incidents/index.php'));}}$pageTitle='Report Incident';$navItems=[['icon'=>'bi-flag','label'=>'Incidents','href'=>url('views/house-master/incidents/index.php'),'active'=>true]];require APP_ROOT.'/app/views/components/header.php';require APP_ROOT.'/app/views/components/sidebar.php';?>
<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><div class="content-wrapper"><div class="card stat-card p-4" style="max-width:760px"><h5 class="mb-3">Report Incident</h5><form method="POST"><div class="row g-3"><div class="col-md-6"><label class="form-label">Student</label><select name="studentId" class="form-select" required><option value="">Select student</option><?php foreach($students as $student):?><option value="<?=e((string)($student['id']??''))?>"><?=e(trim(($student['firstName']??'').' '.($student['lastName']??'')))?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Incident title</label><input name="title" class="form-control" required></div><div class="col-md-6"><label class="form-label">Priority</label><select name="priority" class="form-select"><option value="low">Low</option><option value="medium" selected>Medium</option><option value="high">High</option></select></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" class="form-control" rows="5" required></textarea></div></div><div class="mt-4"><button class="btn btn-primary">Submit incident</button> <a class="btn btn-outline-secondary" href="<?=url('views/house-master/incidents/index.php')?>">Cancel</a></div></form></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php'; ?>